import { roundCents } from './money.mjs';
export function total(lines, discountRate = 0) {
  if (!Number.isFinite(discountRate) || discountRate < 0 || discountRate > 1) {
    throw new RangeError(`discountRate must be a finite number between 0 and 1, got ${discountRate}`);
  }
  const subtotal = lines.reduce((sum, line) => sum + line.quantity * line.unitPrice, 0);
  return roundCents(subtotal * (1 - discountRate));
}

import { total } from './pricing.mjs';
export function makeReceipt(lines, discountRate = 0) {
  return { amount: total(lines, discountRate), currency: 'DKK' };
}

